TEXT ·rowMaxAVX512(SB), NOSPLIT, $0-20
	MOVQ    x+0(FP), AX
	MOVQ    n+8(FP), CX
	VMOVUPS (AX), Z0
	TESTQ   CX, CX
	JZ      rowMaxAVX512_done

rowMaxAVX512_loop:
	VMAXPS (AX), Z0, Z0
	ADDQ   $0x00000040, AX
	SUBQ   $0x00000010, CX
	JNZ    rowMaxAVX512_loop

rowMaxAVX512_done:
	VEXTRACTF64X4 $0x01, Z0, Y1
	VMAXPS        Y1, Y0, Y0
	VEXTRACTF128  $0x01, Y0, X1
	VMAXPS        X1, X0, X0
	VPERMILPS     $0x4e, X0, X1
	VMAXPS        X1, X0, X0
	VPERMILPS     $0xb1, X0, X1
	VMAXPS        X1, X0, X0
	MOVSS         X0, ret+16(FP)
	VZEROUPPER
	RET

// func expShiftAVX512(x *float32, n int, shift float32) float32
// Requires: AVX, AVX512DQ, AVX512F, SSE
TEXT ·expShiftAVX512(SB), NOSPLIT, $0-28
	MOVQ         x+0(FP), AX
	MOVQ         n+8(FP), CX
	MOVSS        shift+16(FP), X0
	VBROADCASTSS X0, Z0
	VXORPS       Z2, Z2, Z2
	TESTQ        CX, CX
	JZ           expShiftAVX512_done

expShiftAVX512_loop:
	VMOVUPS      (AX), Z3
	VSUBPS       Z0, Z3, Z3
	VCMPPS       $0x01, exp_lowest<>+0(SB), Z3, K1
	VMAXPS       exp_lowest<>+0(SB), Z3, Z3
	VMINPS       exp_highest<>+0(SB), Z3, Z3
	VMULPS       exp_log2e<>+0(SB), Z3, Z5
	VCVTPS2DQ    Z5, Z4
	VCVTDQ2PS    Z4, Z5
	VFNMADD231PS exp_ln2hi<>+0(SB), Z5, Z3
	VFNMADD231PS exp_ln2lo<>+0(SB), Z5, Z3
	VMOVUPS      exp_p0<>+0(SB), Z5
	VFMADD213PS  exp_p1<>+0(SB), Z3, Z5
	VFMADD213PS  exp_p2<>+0(SB), Z3, Z5
	VFMADD213PS  exp_p3<>+0(SB), Z3, Z5
	VFMADD213PS  exp_p4<>+0(SB), Z3, Z5
	VFMADD213PS  exp_p5<>+0(SB), Z3, Z5
	VMULPS       Z3, Z3, Z6
	VFMADD213PS  Z3, Z6, Z5
	VADDPS       exp_one<>+0(SB), Z5, Z5
	VPADDD       exp_bias<>+0(SB), Z4, Z4
	VPSLLD       $0x17, Z4, Z4
	VMULPS       Z4, Z5, Z5
	VPXORD       Z1, Z1, Z1
	VBLENDMPS    Z1, Z5, K1, Z5
	VMOVUPS      Z5, (AX)
	VADDPS       Z5, Z2, Z2
	ADDQ         $0x00000040, AX
	SUBQ         $0x00000010, CX
	JNZ          expShiftAVX512_loop

expShiftAVX512_done:
	VEXTRACTF64X4 $0x01, Z2, Y0
	VADDPS        Y0, Y2, Y2
	VEXTRACTF128  $0x01, Y2, X0
	VADDPS        X0, X2, X2
	VPERMILPS     $0x4e, X2, X0
	VADDPS        X0, X2, X2
	VPERMILPS     $0xb1, X2, X0
	VADDPS        X0, X2, X2
	MOVSS         X2, ret+24(FP)
	VZEROUPPER
	RET

// func scaleRowAVX512(x *float32, n int, a float32)
// Requires: AVX, AVX512F, SSE
TEXT ·scaleRowAVX512(SB), NOSPLIT, $0-20
	MOVQ         x+0(FP), AX
	MOVQ         n+8(FP), CX
	MOVSS        a+16(FP), X0
	VBROADCASTSS X0, Z0
	TESTQ        CX, CX
	JZ           scaleRowAVX512_done

scaleRowAVX512_loop:
	VMULPS  (AX), Z0, Z1
	VMOVUPS Z1, (AX)
	ADDQ    $0x00000040, AX
	SUBQ    $0x00000010, CX
	JNZ     scaleRowAVX512_loop

scaleRowAVX512_done:
	VZEROUPPER
	RET

// func softmaxGradAVX512(p *float32, dp *float32, n int, d float32)
// Requires: AVX, AVX512F, SSE
TEXT ·softmaxGradAVX512(SB), NOSPLIT, $0-28
	MOVQ         p+0(FP), AX
	MOVQ         dp+8(FP), CX
	MOVQ         n+16(FP), DX
	MOVSS        d+24(FP), X0
	VBROADCASTSS X0, Z0
	TESTQ        DX, DX
	JZ           softmaxGradAVX512_done

softmaxGradAVX512_loop:
	VMOVUPS (CX), Z1
	VSUBPS  Z0, Z1, Z1
	VMULPS  (AX), Z1, Z1
	VMOVUPS Z1, (AX)
	ADDQ    $0x00000040, AX
	ADDQ    $0x00000040, CX
	SUBQ    $0x00000010, DX
	JNZ     softmaxGradAVX512_loop

softmaxGradAVX512_done:
	VZEROUPPER
	RET

// func dotAVX512(x *float32, y *float32, n int) float32
// Requires: AVX, AVX512DQ, AVX512F, SSE
TEXT ·dotAVX512(SB), NOSPLIT, $0-28
	MOVQ   x+0(FP), AX
	MOVQ   y+8(FP), CX
	MOVQ   n+16(FP), DX
	VXORPS Z0, Z0, Z0
	VXORPS Z1, Z1, Z1
	VXORPS Z2, Z2, Z2
	VXORPS Z3, Z3, Z3
	CMPQ   DX, $0x00000040
	JL     dotAVX512_tail

dotAVX512_wide:
	VMOVUPS     (AX), Z4
	VFMADD231PS (CX), Z4, Z0
	VMOVUPS     64(AX), Z4
	VFMADD231PS 64(CX), Z4, Z1
	VMOVUPS     128(AX), Z4
	VFMADD231PS 128(CX), Z4, Z2
	VMOVUPS     192(AX), Z4
	VFMADD231PS 192(CX), Z4, Z3
	ADDQ        $0x00000100, AX
	ADDQ        $0x00000100, CX
	SUBQ        $0x00000040, DX
	CMPQ        DX, $0x00000040
	JGE         dotAVX512_wide

dotAVX512_tail:
	TESTQ DX, DX
	JZ    dotAVX512_done

dotAVX512_loop:
	VMOVUPS     (AX), Z4
	VFMADD231PS (CX), Z4, Z0
	ADDQ        $0x00000040, AX
	ADDQ        $0x00000040, CX
	SUBQ        $0x00000010, DX
	JNZ         dotAVX512_loop

dotAVX512_done:
	VADDPS        Z1, Z0, Z0
	VADDPS        Z3, Z2, Z2
	VADDPS        Z2, Z0, Z0
	VEXTRACTF64X4 $0x01, Z0, Y1
	VADDPS        Y1, Y0, Y0
	VEXTRACTF128  $0x01, Y0, X1
	VADDPS        X1, X0, X0
	VPERMILPS     $0x4e, X0, X1
	VADDPS        X1, X0, X0
	VPERMILPS     $0xb1, X0, X1
	VADDPS        X1, X0, X0
	MOVSS         X0, ret+24(FP)
	VZEROUPPER
	RET

// func exp2AVX512(dst *float32, src *float32, n int)
// Requires: AVX, AVX512F
TEXT ·exp2AVX512(SB), NOSPLIT, $0-24
	MOVQ  dst+0(FP), AX
	MOVQ  src+8(FP), CX
	MOVQ  n+16(FP), DX
	TESTQ DX, DX
	JZ    exp2AVX512_done

exp2AVX512_loop:
	VMOVUPS     (CX), Z0
	VMAXPS      exp_exp2lo<>+0(SB), Z0, Z0
	VMINPS      exp_exp2hi<>+0(SB), Z0, Z0
	VCVTPS2DQ   Z0, Z1
	VCVTDQ2PS   Z1, Z2
	VSUBPS      Z2, Z0, Z0
	VMOVUPS     exp_q0<>+0(SB), Z2
	VFMADD213PS exp_q1<>+0(SB), Z0, Z2
	VFMADD213PS exp_q2<>+0(SB), Z0, Z2
	VFMADD213PS exp_q3<>+0(SB), Z0, Z2
	VFMADD213PS exp_q4<>+0(SB), Z0, Z2
	VFMADD213PS exp_q5<>+0(SB), Z0, Z2
	VFMADD213PS exp_one<>+0(SB), Z0, Z2
	VPADDD      exp_bias<>+0(SB), Z1, Z1
	VPSLLD      $0x17, Z1, Z1
	VMULPS      Z1, Z2, Z2
	VMOVUPS     Z2, (AX)
	ADDQ        $0x00000040, AX
	ADDQ        $0x00000040, CX
	SUBQ        $0x00000010, DX
	JNZ         exp2AVX512_loop

exp2AVX512_done:
	VZEROUPPER
	RET

