expShiftAVX2_loop:
	VMOVUPS      (AX), Y2
	VSUBPS       Y0, Y2, Y2
	VCMPPS       $0x01, exp_lowest<>+0(SB), Y2, Y3
	VMAXPS       exp_lowest<>+0(SB), Y2, Y2
	VMINPS       exp_highest<>+0(SB), Y2, Y2
	VMULPS       exp_log2e<>+0(SB), Y2, Y5
	VCVTPS2DQ    Y5, Y4
