	VPERMILPS    $0x4e, X1, X0
	VADDPS       X0, X1, X1
	VPERMILPS    $0xb1, X1, X0
	VADDPS       X0, X1, X1
	MOVSS        X1, ret+24(FP)
	VZEROUPPER
	RET

